def solve(n, k):
    if k < n // 2:
        return "NO", []

    colors = list(range(1, k + 1))
    result = []

    for i in range(n // 2):
        result.append((colors[i], colors[-(i + 1)]))

    if n % 2 == 1:
        result.append((colors[n // 2], colors[n // 2]))

    return "YES", result

# Read input
n, k = map(int, input().split())

# Solve the problem
answer, pairs = solve(n, k)

# Print the output
print(answer)
if answer == "YES":
    for pair in pairs:
        print(*pair)
